const module = angular.module("irtech.netcity.school.announcements",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "irtech.netcity.ui-components",
		'ui.tinymce'
	]);

tinymce.init({
	selector: 'textarea',
	language: 'ru',
});

import "angular-ui-tinymce";

import { AnnouncementsRepository } from "./repository.js";
import { ViewAnnouncementsCtrl } from "./view/viewAnnouncementsCtrl.js";
import { EditAnnouncementsCtrl } from "./edit/editAnnouncementCtrl.js";

module
	.filter('trusted', ($sce) => { return (html) => { return $sce.trustAsHtml(_.unescape(html)); }});

module
	.controller("ViewAnnouncementsCtrl", ViewAnnouncementsCtrl)
	.controller("EditAnnouncementsCtrl", EditAnnouncementsCtrl)
	.service("announcementsRepository", AnnouncementsRepository)
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/view/", {
				templateUrl: "/static/dist/app/school/announcements/view/template.html",
				controller: "ViewAnnouncementsCtrl as ctrl"
			})
			.when("/edit/:announcementId?", {
				templateUrl: "/static/dist/app/school/announcements/edit/template.html",
				controller: "EditAnnouncementsCtrl as ctrl"
			})
			.otherwise({
				templateUrl: "/static/dist/app/school/announcements/view/template.html",
				controller: "ViewAnnouncementsCtrl as ctrl"
			});
		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});


