"use strict";

import { BaseRepository } from "approot/global/repository.js";
export class AnnouncementsRepository extends BaseRepository {
	getAll() {
		return this.$http.get("/webapi/announcements", { params: { take: -1 } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getEdit(id) {
		return this.$http.get("/webapi/announcements/edit", {params: {id}})
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getSchoolRoles() {
		return this.$http.get("/webapi/refs/schoolroles", {params: {language: appContext.language}})
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	delete(id) {
		var processing = $.show.processing();
		return this.$http.delete("/webapi/announcements", { params: { id } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	save(editAnnounce) {
		var processing = $.show.processing();
		return this.$http.post("/webapi/announcements", editAnnounce)
			.then(this.handleResponse)
			.catch(this.handleError);
	}
}


