"use strict";

const dateUtils = window.dateUtils;

export class EditAnnouncementsCtrl {
	/*@ngInject*/
	constructor($q, pageContext, $location, $appLoader, announcementsRepository, $routeParams, changeTracker, $alerts){
		this.$q = $q;
		
		this.appContext = appContext;
		this.$appLoader = $appLoader;
		this.$location = $location;

		this.announcementsRepository = announcementsRepository;
		this.changeTracker = changeTracker;
		this.$alerts = $alerts;

		this.announcementId = parseInt($routeParams.announcementId) || 0;


		this.state = {
			dataReady: false,
			createMode: !this.announcementId
		};

		pageContext.parent = {
			title: language.Generic.Announcement.kTitleViewAnn,
			href: `/`
		};
		pageContext.title = this.state.createMode ? language.Generic.Announcement.kTitleAnnounce : language.Generic.Announcement.kEditingAnnouncements;

		this.language = language;
		this.data = {
			announcementId: this.announcementId,
			deleteDateStr: "",
			announcement: null,
			recipientGroups: []
		};

		this.tinymceOptions = {
			menubar: false,
			height : 300,
			paste_as_text: true,
			plugins: 'link image lists table colorpicker textcolor paste',
			toolbar: 'undo redo | bold italic | forecolor backcolor | alignleft aligncenter alignright | bullist numlist | link image',
			init_instance_callback: function (editor) {
				editor.on('Change', function (e) {
					changeTracker.dataWasChanged();
				});
			}
		}

		this.init();

	}

	init(){
		const promises = [];

		this.refsReady = this.announcementsRepository.getSchoolRoles().then((roles) => {
			this.data.recipientGroups = roles;
		});



		setTimeout(() => { dateInput.initDateInputs(new Date().addDays(1), new Date().addYears(1)), null, { format: dateUtils.getDateFormat().format, autoCorrectDates: false } }, 200);

		promises.push(this.refsReady);
		promises.push(this.initAnnounce());

		this.$q.all(promises).then(() => {
			this.syncDate();
			this.initFileAttachments();

			this.state.dataReady = true;
			this.$appLoader.hide();
		});
	}

	initFileAttachments() {
		const files = this.data.announcement.attachments || [];

		this.fa = {
			options: {
				multiple: true,
				showDescription: true
			},
			data: {
				files: files,
				context: {
					announcementId: this.data.announcementId
				}
			}
		}
	}

	initAnnounce() {
		if (this.data.announcementId) {
			const announceLoad = this.announcementsRepository.getEdit(this.data.announcementId)
				.then((announcement) => {
					this.data.announcement = announcement;
					if (announcement.recipientGroup.length === 1 && announcement.recipientGroup[0] === 0) {
						this.refsReady.then(() => {
							announcement.recipientGroup = _.map(this.data.recipientGroups, (g) => g.id);
						});	
					}
					return this.data.announcement;
				});

			return announceLoad;
		} else {
			this.data.announcement = {
				deleteDate: new Date().addDays(10),
				recipientGroup: [],
				title: "",
				description: ""
			};

			return Promise.resolve(this.data.announcement);
		}
	}

	syncDate() {
		this.data.deleteDateStr = dateUtils.date2str(new Date(this.data.announcement.deleteDate));
	}

	toggleRecipientGroup (groupId) {
		if (groupId === -1) {
			if (this.data.announcement.recipientGroup.length === this.data.recipientGroups.length) {
				this.data.announcement.recipientGroup = [];
			} else {
				this.data.announcement.recipientGroup = this.data.recipientGroups.map(x => x.id);
			}
		} else {
			var idx = this.data.announcement.recipientGroup.indexOf(groupId);
			if (idx > -1) {
				this.data.announcement.recipientGroup.splice(idx, 1);
			}
			else {
				this.data.announcement.recipientGroup.push(groupId);
			}
		}
	}

	save() {
		this.announceForm.$displayErrors = true;
		if (!this.announceForm.$valid) {
			return;
		}

		if (this.data.announcement.recipientGroup.length === 0) {
			$.show.message("Выберите получателя сообщения");
			return;
		}

		if (!dateUtils.str2date(this.data.deleteDateStr)) {
			$.show.error(this.language.Generic.Announcement.kErrorBadDeletingDate);
			return;
		}

		const deleteDate = dateUtils.str2date(this.data.deleteDateStr);

		if (deleteDate < new Date() || deleteDate > new Date().addYears(1)) {
			$.show.error(this.language.Generic.Announcement.kErrorBadDeletingDate);
			return;
		}

		this.data.announcement.deleteDate = deleteDate;

		const mapFunc = (f) => ({ id: f.id });
		this.data.announcement.attachments = _.map(this.fa.data.files, mapFunc);

		this.announcementsRepository.save(this.data.announcement).then(() => {
			this.changeTracker.clearDataChanges();
			if (this.state.createMode) {
				this.$alerts.success(language.Generic.Announcement.kAnnouncementIsSent);
			} else {
				this.$alerts.success(language.Generic.Announcement.kAnnouncementIsSaved);
			}
			
			this.$location.path(`/`);
		});
	}

	deleteDatePaste(){}

	reset() {
		this.initAnnounce().then(() => {
			this.syncDate();
			this.initFileAttachments();
		});
	}
}


