"use strict";

import * as Roles from "approot/global/references/roles.js";
import * as Rights from "approot/global/references/rights.js";

export class ViewAnnouncementsCtrl {
	/*@ngInject*/
	constructor(pageContext, appContext, $location, $appLoader, announcementsRepository, downloadService, $alerts){
		this.appContext = appContext;
		this.$appLoader = $appLoader;
		this.$location = $location;
		this.announcementsRepository = announcementsRepository;
		this.downloadService = downloadService;
		this.$alerts = $alerts;

		pageContext.parent = null;
		pageContext.title = language.Generic.Announcement.kTitleViewAnn;

		this.language = language;
		this.isAdmin = (appContext.roles.indexOf(Roles.admin) >= 0);
		this.state = {
			dataReady: false,
			emptyData: false,
			canRemove: false,
			canPost: false
		};

		this.data = {
			announcements: null,
			selected: []
		};

		this.load();
	}

	add(){
		this.$location.path(`/edit/`);
	}

	edit(announcement){
		this.$location.path(`/edit/${announcement.id}`);
	}

	delete(){
		if (!this.data.selected.length) {
			$.show.message(this.language.Generic.Announcement.kCheckMessageToDelete);
			return;
		}
		$.show.confirmation(this.language.Generic.Announcement.kAreYouSureToDelete)
			.then(() => {
				this.announcementsRepository.delete(this.data.selected).then(() => {
					this.$alerts.success(this.language.Generic.Announcement.kAttention1);
					this.data.selected = [];
					this.load();
				});
			});
	}


	load(){
		this.state.dataReady = false;

		if (this.isAdmin) {
			this.state.readOnly = false;
		}

		this.state.canPost = this.isAdmin || appContext.hasAnyRight([Rights.arAnnouncementPost]);

		this.announcementsRepository
			.getAll()
			.then((announcements) => {
				//устанавливаю локальное дату и время публикации объявления
				for (let i = 0; i < announcements.length; i++) {
					let announcement = announcements[i];
					announcement.postDateLocale = dateUtils.getLocalDateTime(announcement.postDate);
				}

				this.data.announcements = announcements;
				this.state.canRemove = this.isAdmin || _.some(announcements, (a) => a.author && (a.author.id == appContext.userId));
				this.state.dataReady = true;
				this.state.emptyData = this.data.announcements.length === 0;
				this.$appLoader.hide();
			});
	}

	toggleChecks(id) {
		var idx = this.data.selected.indexOf(id);
		if (idx > -1) {
			this.data.selected.splice(idx, 1);
		}
		else {
			this.data.selected.push(id);
		}
	}

	canEdit(announce) {
		return this.state.canPost && !announce.em && (this.isAdmin || (announce.author && announce.author.id == this.appContext.userId));
	}

	getPhotoUrl(userId) {
		return `/webapi/users/photo?at=${this.appContext.at}&userId=${userId}`;
	}

	downloadAttach(attach) {
		this.downloadService.downloadAttachment(attach.id, attach.originalFileName);
	}
}


